insert into RRL_KNOWLEDGE_SPACE(SPACE_ID,TITLE,VERSION_NO)values('general',N'Работа с системой',1);
insert into RRL_KNOWLEDGE_ARTICLE(ARTICLE_ID,SPACE_ID,CURRENT_VERSION,PUBLISHED_VERSION)values('using-help','general',1,1);
insert into RRL_KNOWLEDGE_REV(ARTICLE_ID,VERSION_NO,STATE,PAYLOAD_JSON,ACTOR,REASON)values('using-help',1,'PUBLISHED',to_clob(q'~{"article_id":"using-help","title":"Как пользоваться встроенной справкой","summary":"Поиск и связанные инструкции без ухода с рабочего экрана.","body":"Подсказка объясняет, что изменится после нажатия и зачем это нужно. Вопрос рядом с командой открывает подробное объяснение.\n\nОткройте «Справка» или нажмите F1. Найдите тему по словам, откройте статью и связанные инструкции. Закройте панель кнопкой или Escape: рабочий экран останется открытым.\n\nПервая версия содержит подготовленные статьи. Редактор и публикация через интерфейс — последующие этапы. Справка не выполняет операции и не выдаёт права.","related":["access-model","operation-recovery"],"sources":["wiki/concepts/ui_interaction_rules.md","wiki/architecture/retailcase_scoped_access_and_knowledge.md"],"space_id":"general","required_permissions":[]}~'),N'SYSTEM',N'Initial curated wiki publication');
insert into RRL_KNOWLEDGE_ARTICLE(ARTICLE_ID,SPACE_ID,CURRENT_VERSION,PUBLISHED_VERSION)values('access-model','general',1,1);
insert into RRL_KNOWLEDGE_REV(ARTICLE_ID,VERSION_NO,STATE,PAYLOAD_JSON,ACTOR,REASON)values('access-model',1,'PUBLISHED',to_clob(q'~{"article_id":"access-model","title":"Роли и области ответственности","summary":"Роли, группы складов, РЦ и магазинов; совместимость существующего доступа.","body":"Принята модель: роль определяет действия, область — объекты. Например: диспетчер РЦ Север и аудитор всей сети. Глобальное чтение не даёт глобального редактирования другой роли.\n\nГруппы объектов и доступа различаются. Подчинение не выдаёт права. Замещение ограничено сроком, делегирование — мандатом.\n\nНовый механизм назначений находится в разработке. Сейчас полномочия определяются существующей RUSERS/USER_GROUP/RIGHTS. Чтение статьи и выбор рабочего места права не меняют.","related":["using-help","operation-recovery"],"sources":["wiki/architecture/retailcase_scoped_access_and_knowledge.md","wiki/concepts/legacy_rights_model.md"],"space_id":"general","required_permissions":[]}~'),N'SYSTEM',N'Initial curated wiki publication');
insert into RRL_KNOWLEDGE_ARTICLE(ARTICLE_ID,SPACE_ID,CURRENT_VERSION,PUBLISHED_VERSION)values('operation-recovery','general',1,1);
insert into RRL_KNOWLEDGE_REV(ARTICLE_ID,VERSION_NO,STATE,PAYLOAD_JSON,ACTOR,REASON)values('operation-recovery',1,'PUBLISHED',to_clob(q'~{"article_id":"operation-recovery","title":"Если ответ на команду потерян","summary":"Неизвестный результат не означает отказ; как избежать повторного движения.","body":"При потере связи команда могла выполниться. Не создавайте новое подтверждение того же физического действия, пока исход прежнего не установлен. Используйте восстановление конкретного рабочего экрана.\n\nНеизменный запрос повторяется с прежним operation_id. Изменение количества, назначения или версии — другая команда; сначала нужно установить исход предыдущей.\n\nСостояние «отправлено» или «результат неизвестен» не подтверждает товарный факт. Локальная проводка и доставка сообщения во внешнюю систему имеют отдельные статусы.\n\nЕдиный интерфейс восстановления всех рабочих мест ещё внедряется. Статья описывает общий принцип, а не наличие одинаковой кнопки везде.","related":["using-help"],"sources":["wiki/requirements/stock_posting_core_tz.md","wiki/concepts/retailcase_roles_kpi_command_proposal_20261014.md"],"space_id":"general","required_permissions":[]}~'),N'SYSTEM',N'Initial curated wiki publication');
